const audio=document.querySelector('#audio'),play=document.querySelector('#play'),seek=document.querySelector('#seek'),volume=document.querySelector('#volume'),speed=document.querySelector('#speed'),status=document.querySelector('#status');
const fmt=t=>`${Math.floor((t||0)/60).toString().padStart(2,'0')}:${Math.floor((t||0)%60).toString().padStart(2,'0')}`;
const bars=Array.from({length:64},(_,i)=>{const h=8+Math.round(Math.abs(Math.sin(i*1.7)*Math.cos(i*.23))*32);return `<rect x="${i*8}" y="${(48-h)/2}" width="4" height="${h}" rx="2" fill="#DCE3DD"/>`}).join('');
document.querySelector('#wave').innerHTML=bars;audio.volume=.7;
function render(){const duration=Number.isFinite(audio.duration)?audio.duration:0,progress=duration?audio.currentTime/duration:0;seek.value=progress*100;seek.setAttribute('aria-valuetext',`${fmt(audio.currentTime)} de ${fmt(duration)}`);document.querySelector('#elapsed').textContent=fmt(audio.currentTime);document.querySelector('#duration').textContent=fmt(duration);document.querySelectorAll('#wave rect').forEach((bar,i)=>bar.setAttribute('fill',i/64<progress?'#287B67':'#DCE3DD'));play.setAttribute('aria-label',audio.paused?'Reproducir':'Pausar');play.innerHTML=audio.paused?'<svg viewBox="0 0 24 24"><path d="M8 4L21 12L8 20Z"/></svg>':'<svg viewBox="0 0 24 24"><path d="M6 4h4v16H6zM14 4h4v16h-4z"/></svg>'}
play.onclick=async()=>{if(audio.paused){try{await audio.play()}catch{status.textContent='No se pudo reproducir. Probá cargar otro archivo de audio.'}}else audio.pause()};
['loadedmetadata','timeupdate','play','pause','ended','durationchange'].forEach(event=>audio.addEventListener(event,render));
seek.oninput=()=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*seek.value/100};document.querySelector('#back').onclick=()=>audio.currentTime=Math.max(0,audio.currentTime-15);
const rates=[1,1.25,1.5,1.75,2,.75];speed.onclick=()=>{audio.playbackRate=rates[(rates.indexOf(audio.playbackRate)+1)%rates.length];speed.textContent=audio.playbackRate+'×';speed.setAttribute('aria-label',`Velocidad: ${audio.playbackRate}`)};
volume.oninput=()=>{audio.volume=+volume.value;audio.muted=false;updateMute()};function updateMute(){const muted=audio.muted||audio.volume===0;document.querySelector('#mute').setAttribute('aria-label',muted?'Activar sonido':'Silenciar');document.querySelector('#mute').style.opacity=muted?'.45':'1'}document.querySelector('#mute').onclick=()=>{audio.muted=!audio.muted;updateMute()};
let localUrl;document.querySelector('#file').onchange=event=>{const file=event.target.files[0];if(!file)return;audio.pause();if(localUrl)URL.revokeObjectURL(localUrl);localUrl=URL.createObjectURL(file);audio.src=localUrl;audio.load();status.textContent=file.name+' · Archivo local';render()};audio.addEventListener('error',()=>status.textContent='No se pudo cargar el audio. Probá con un archivo MP3, M4A o WAV.');render();
